        "LockNote" -> store.lockNote(key)?.toRow()
        "UnlockNote" -> store.unlockNote(key)?.toRow()
        "RenameText" -> store.renameText(key)?.toRow()
        "BareEdit" -> store.bareEdit(key)?.toRow()
        "BareEditRefusal" -> store.bareEditRefusal(key)?.toRow()
        "SafeEdit" -> store.safeEdit(key)?.toRow()
        "EditApplication" -> store.editApplication(key)?.toRow()
        "EditRefusal" -> store.editRefusal(key)?.toRow()
        "TransientEditRefusal" -> store.transientEditRefusal(key)?.toRow()
        else -> null
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Note" -> store.allNotes().map { it.toRow() }
        "LockNote" -> store.allLockNotes().map { it.toRow() }
        "UnlockNote" -> store.allUnlockNotes().map { it.toRow() }
        "RenameText" -> store.allRenameTexts().map { it.toRow() }
        "BareEdit" -> store.allBareEdits().map { it.toRow() }
        "BareEditRefusal" -> store.allBareEditRefusals().map { it.toRow() }
        "SafeEdit" -> store.allSafeEdits().map { it.toRow() }
        "EditApplication" -> store.allEditApplications().map { it.toRow() }
        "EditRefusal" -> store.allEditRefusals().map { it.toRow() }
        "TransientEditRefusal" -> store.allTransientEditRefusals().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencing(shape: String, field: String, target: Ref.Persisted): List<Row> = when {
        shape == "LockNote" && field == "note" -> store.lockNotesByNote(target).map { it.toRow() }
        shape == "UnlockNote" && field == "note" -> store.unlockNotesByNote(target).map { it.toRow() }
        shape == "RenameText" && field == "note" -> store.renameTextsByNote(target).map { it.toRow() }
        shape == "BareEdit" && field == "note" -> store.bareEditsByNote(target).map { it.toRow() }
        shape == "BareEditRefusal" && field == "edit" -> store.bareEditRefusalsByEdit(target).map { it.toRow() }
        shape == "SafeEdit" && field == "note" -> store.safeEditsByNote(target).map { it.toRow() }
        shape == "EditApplication" && field == "edit" -> store.editApplicationsByEdit(target).map { it.toRow() }
        shape == "EditRefusal" && field == "edit" -> store.editRefusalsByEdit(target).map { it.toRow() }
        shape == "TransientEditRefusal" && field == "note" -> store.transientEditRefusalsByNote(target).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Note")
            questions.lockedNoteCandidates.match(filter)?.let { h -> return store.lockedNoteCandidates().map { it.toRow() } }
        if (shape == "BareEdit")
            questions.applicableBareEditCandidates.match(filter)?.let { h -> return store.applicableBareEditCandidates().map { it.toRow() } }
        if (shape == "BareEdit")
            questions.refusedBareEditCandidates.match(filter)?.let { h -> return store.refusedBareEditCandidates().map { it.toRow() } }
        if (shape == "SafeEdit")
            questions.unhandledSafeEditCandidates.match(filter)?.let { h -> return store.unhandledSafeEditCandidates().map { it.toRow() } }
        if (shape == "SafeEdit")
            questions.applicableSafeEditCandidates.match(filter)?.let { h -> return store.applicableSafeEditCandidates().map { it.toRow() } }
        if (shape == "SafeEdit")
            questions.refusedSafeEditCandidates.match(filter)?.let { h -> return store.refusedSafeEditCandidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
    }
